s, exact job, charges and appointment directly. Current availability is unconfirmed.", "note": "First-party website information checked November 28, 2026, fresh HTTP200: business identity, public phone, published office/dispatch address, advertised services and individually named cities. Contact https://valleycityplumbing.com/contact/ and services https://valleycityplumbing.com/services/ establish only Tracy/Lathrop/Manteca. No owner contact, current availability, emergency response time, license/insurance validation, workmanship or ratings confirmed. No provider photos copied."}]'::jsonb) loop
if exists(select 1 from public.businesses where lower(rtrim(coalesce(website,''),'/'))=lower(rtrim(r->>'website','/')) or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10) or lower(name)=lower(r->>'name')) then raise exception 'Duplicate candidate: %',r->>'name';end if;
insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,needs_review,source,source_url,verification_source,verified_at)values(r->>'name','Home Services',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,false,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now())returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note)values(bid,r->>'source_url',array['identity','public phone','website','advertised services','explicit service cities','scope and limitations'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
select to_jsonb(b) into applied from public.businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'CORE-01 individually checked plumbing service expansion; website information only',r->>'source_url');
end loop;end $curate$;
